class Solution {
    public String smallestString(String s){
        char[] chars=s.toCharArray();
        int index=0;
        while(index<chars.length&&chars[index]=='a')index++;
        if(index==chars.length)chars[chars.length-1]='z';
        else while(index<chars.length&&chars[index]!='a'){
            chars[index]--;
            index++;
        }
        return new String(chars);
    }
}

code.kotlin:
class Solution {
    fun smallestString(s:String):String{
        val chars=s.toCharArray();
        var index=0;
        while(index<chars.size&&chars[index]=='a')index++;
        if(index==chars.size)chars[chars.lastIndex]='z' else while(index<chars.size&&chars[index]!='a'){
            chars[index]=(chars[index].code-1).toChar();
            index++
        };
        return String(chars)
    }
}

